package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.*;
import thaumcraft.api.aspects.*;
final class AwakenedChestAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened chest: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);var oldPos=p.position();var oldData=p.getPersistentData().copy();var abilities=p.getAbilities();boolean oldCreative=abilities.instabuild,oldMayfly=abilities.mayfly,oldFlying=abilities.flying,oldInvulnerable=abilities.invulnerable;var stack=new ItemStack(AwakenedChest.ITEM.get());p.getInventory().clearContent();p.removeAllEffects();p.setPos(30.5,290,30.5);AwakenedArmorStatus.set(p,true);abilities.instabuild=false;abilities.mayfly=false;abilities.flying=false;abilities.invulnerable=false;
 try{p.setItemSlot(EquipmentSlot.CHEST,stack);AwakenedChest.update(p,true);check(abilities.mayfly&&!abilities.flying&&!abilities.invulnerable,"grants flight permission without forcing takeoff/godmode");abilities.flying=true;AwakenedChest.update(p,true);check(abilities.flying&&abilities.mayfly,"flight remains active");AwakenedArmorItem.toggle(stack);abilities.invulnerable=true;AwakenedChest.update(p,true);check(!abilities.mayfly&&!abilities.flying&&!abilities.invulnerable,"original per-item disabled revokes owned survival abilities");AwakenedArmorItem.toggle(stack);AwakenedChest.update(p,true);AwakenedArmorStatus.set(p,false);AwakenedChest.update(p,true);check(!abilities.mayfly,"global disable revokes flight");AwakenedArmorStatus.set(p,true);AwakenedChest.update(p,false);check(!abilities.mayfly,"configuration disables flight");AwakenedChest.update(p,true);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);AwakenedChest.update(p,true);check(!abilities.mayfly,"unequip removes owned flight");abilities.mayfly=true;AwakenedChest.update(p,true);check(abilities.mayfly,"untracked external flight untouched");p.setItemSlot(EquipmentSlot.CHEST,stack);abilities.instabuild=true;abilities.invulnerable=true;abilities.flying=true;AwakenedChest.update(p,true);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);AwakenedChest.update(p,true);check(abilities.mayfly&&abilities.flying&&abilities.invulnerable,"creative abilities preserved on removal");abilities.instabuild=false;abilities.mayfly=false;abilities.flying=false;abilities.invulnerable=false;p.setItemSlot(EquipmentSlot.CHEST,stack);
 var owner=EntityType.COW.create(level);var arrow=EntityType.ARROW.create(level);arrow.setOwner(owner);arrow.setPos(p.getX()+1,p.getY()+1,p.getZ());arrow.setDeltaMovement(1,0,0);level.addFreshEntity(arrow);var own=EntityType.ARROW.create(level);own.setOwner(p);own.setPos(p.getX()+1,p.getY()+1,p.getZ()+1);own.setDeltaMovement(1,0,0);level.addFreshEntity(own);try{var before=arrow.position();var ownPos=own.position();AwakenedChest.update(p,false);check(arrow.position().x>before.x&&arrow.getDeltaMovement().x==1&&arrow.getOwner()==owner,"free displacement shield while flight configuration off,owner/motion retained");check(own.position().equals(ownPos),"own projectiles excluded");arrow.setPos(before);AwakenedArmorItem.toggle(stack);AwakenedChest.update(p,false);check(arrow.position().equals(before),"individual disabled no shield");AwakenedArmorItem.toggle(stack);AwakenedArmorStatus.set(p,false);AwakenedChest.update(p,false);check(arrow.position().equals(before),"global disabled no shield");}finally{arrow.discard();own.discard();owner.discard();}
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHORCLOTH_CHEST_GEM")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(parts.size()==12&&parts.get(1).is(KamiResources.item(KamiResources.Kind.ICHOR))&&parts.get(2).is(KamiResources.item(KamiResources.Kind.ICHOR))&&parts.get(6).is(ThaumicTinkererModern.FOCUS_FLIGHT.get())&&parts.get(7).is(FocusResearch.item("hover_harness"))&&parts.get(8).is(ThaumicTinkererModern.FOCUS_DEFLECT.get())&&parts.get(11).is(Items.ARROW),"original twelve components");Aspect[] aspects={Aspect.AIR,Aspect.ARMOR,Aspect.FLIGHT,Aspect.ORDER,Aspect.LIGHT,Aspect.ELDRITCH,Aspect.SENSES};int[] amounts={50,32,32,32,64,16,16};check(recipe.instability()==13&&recipe.aspects().size()==7,"instability/aspect count");for(int i=0;i<7;i++)check(recipe.aspects().getAmount(aspects[i])==amounts[i],"original exact aspect cost");var input=new ItemStack(KamiArmor.ITEMS.get(1).get());check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of(recipe.research()))==recipe&&dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,input,java.util.Set.of())==null&&recipe.outputStack(input).is(AwakenedChest.ITEM.get()),"native infusion/research lock/output");var r=thaumcraft.api.research.ResearchCategories.getResearch(recipe.research());check(r instanceof KamiResearch&&r.displayColumn==17&&r.displayRow==7&&java.util.Arrays.equals(r.parents,new String[]{"ICHORCLOTH_ARMOR"})&&r.getPages().length==2,"original research progression");check(AwakenedChest.ITEM.get().getDefense()==8&&AwakenedChest.ITEM.get().getVisDiscount(stack,p,Aspect.AIR)==4&&!stack.isDamageableItem(),"original inherited armor/discount/indestructibility");System.out.println("TT AWAKENED CHEST AUDIT: ALL PASS (flight ownership/config/toggles/removal/creative,free native projectile shield/exclusions,12part infusion/exact costs/research,inherited armor)");
 }finally{p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);AwakenedChest.update(p,false);abilities.instabuild=oldCreative;abilities.mayfly=oldMayfly;abilities.flying=oldFlying;abilities.invulnerable=oldInvulnerable;p.getInventory().clearContent();p.setPos(oldPos);var data=p.getPersistentData();for(var key:new java.util.HashSet<>(data.getAllKeys()))data.remove(key);data.merge(oldData);}
 }
}
